# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM İNANÇ ESASLARI (ÂMENTÜ) — I. BÖLÜM</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. ALLAH\'A İMAN (Tevhid)</text>\n  <text x="38" y="96" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Zâtî Sıfatlar:</tspan> Vücûd, Kıdem,</text>\n  <text x="46" y="112" font-size="11" fill="#1e3a8a">Bekâ, Vahdâniyet, Muhâlefetün</text>\n  <text x="46" y="128" font-size="11" fill="#1e3a8a">li\'l-havâdis, Kıyâm bi-nefsihî</text>\n  <text x="38" y="152" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Subûtî Sıfatlar:</tspan> Hayat, İlim,</text>\n  <text x="46" y="168" font-size="11" fill="#1e3a8a">Semi, Basar, İrade, Kudret,</text>\n  <text x="46" y="184" font-size="11" fill="#1e3a8a">Kelam, Tekvin (Yaratma)</text>\n  <text x="38" y="212" font-size="11" font-weight="bold" fill="#1d4ed8">Esas: Şirkten arınmış tevhid</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. MELEKLERE İMAN</text>\n  <text x="260" y="96" font-size="11" fill="#14532d">• <tspan font-weight="bold">Cebrâil:</tspan> Vahiy meleği</text>\n  <text x="260" y="116" font-size="11" fill="#14532d">• <tspan font-weight="bold">Mikâil:</tspan> Tabiat ve rızık olayları</text>\n  <text x="260" y="136" font-size="11" fill="#14532d">• <tspan font-weight="bold">İsrâfil:</tspan> Sûr\'a üfüren melek</text>\n  <text x="260" y="156" font-size="11" fill="#14532d">• <tspan font-weight="bold">Azrâil:</tspan> Ölüm meleği</text>\n  <text x="260" y="176" font-size="11" fill="#14532d">• <tspan font-weight="bold">Kirâmen Kâtibîn:</tspan> Yazıcı melekler</text>\n  <text x="260" y="196" font-size="11" fill="#14532d">• <tspan font-weight="bold">Münker - Nekir:</tspan> Kabir sorgusu</text>\n  <text x="260" y="216" font-size="11" font-weight="bold" fill="#15803d">Nurdan yaratılmış, masum varlıklar</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. KİTAPLARA İMAN</text>\n  <text x="483" y="96" font-size="11" fill="#78350f">• <tspan font-weight="bold">Suhuf (100 Sayfa):</tspan> Hz. Âdem (10),</text>\n  <text x="491" y="112" font-size="11" fill="#78350f">Hz. Şît (50), Hz. İdris (30),</text>\n  <text x="491" y="128" font-size="11" fill="#78350f">Hz. İbrahim (10)</text>\n  <text x="483" y="150" font-size="11" fill="#78350f">• <tspan font-weight="bold">Tevrat:</tspan> Hz. Musa (a.s.)</text>\n  <text x="483" y="168" font-size="11" fill="#78350f">• <tspan font-weight="bold">Zebur:</tspan> Hz. Davud (a.s.)</text>\n  <text x="483" y="186" font-size="11" fill="#78350f">• <tspan font-weight="bold">İncil:</tspan> Hz. İsa (a.s.)</text>\n  <text x="483" y="208" font-size="11" font-weight="bold" fill="#b45309">• Kur\'an-ı Kerim: Hz. Muhammed</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM İNANÇ ESASLARI (ÂMENTÜ) — II. BÖLÜM</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">4. PEYGAMBERLERE İMAN</text>\n  <text x="38" y="96" font-size="11" fill="#581c87">• <tspan font-weight="bold">Sıdk:</tspan> Doğru ve dürüst olmak</text>\n  <text x="38" y="116" font-size="11" fill="#581c87">• <tspan font-weight="bold">Emanet:</tspan> Güvenilir olmak</text>\n  <text x="38" y="136" font-size="11" fill="#581c87">• <tspan font-weight="bold">Fetanet:</tspan> Üstün akıl ve zekâ</text>\n  <text x="38" y="156" font-size="11" fill="#581c87">• <tspan font-weight="bold">İsmet:</tspan> Günahtan korunmuşluk</text>\n  <text x="38" y="176" font-size="11" fill="#581c87">• <tspan font-weight="bold">Tebliğ:</tspan> Vahyi eksiksiz iletmek</text>\n  <text x="38" y="204" font-size="11" font-weight="bold" fill="#7e22ce">Kur\'an\'da 25 peygamber ismi geçer.</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#e0f2fe" stroke="#0284c7" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">5. AHİRET GÜNÜNE İMAN</text>\n  <text x="260" y="96" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Berzah:</tspan> Kabir hayatı</text>\n  <text x="260" y="116" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Kıyamet &amp; Ba\'s:</tspan> Yeniden diriliş</text>\n  <text x="260" y="136" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Haşir &amp; Mahşer:</tspan> Toplanma yeri</text>\n  <text x="260" y="156" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Hesap &amp; Mizan:</tspan> Adalet terazisi</text>\n  <text x="260" y="176" font-size="11" fill="#0c4a6e">• <tspan font-weight="bold">Cennet &amp; Cehennem:</tspan> Ebedi yurt</text>\n  <text x="260" y="204" font-size="11" font-weight="bold" fill="#0284c7">Dünya ahiretin tarlasıdır.</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#9d174d">6. KADER VE KAZAYA İMAN</text>\n  <text x="483" y="96" font-size="11" fill="#831843">• <tspan font-weight="bold">Kader:</tspan> Allah\'ın ezeli ilim ve</text>\n  <text x="491" y="112" font-size="11" fill="#831843">iradesiyle her şeyi ölçüyle</text>\n  <text x="491" y="128" font-size="11" fill="#831843">takdir ve planlaması</text>\n  <text x="483" y="150" font-size="11" fill="#831843">• <tspan font-weight="bold">Kaza:</tspan> Planlanan olayın</text>\n  <text x="491" y="166" font-size="11" fill="#831843">zamanı gelince yaratılması</text>\n  <text x="483" y="190" font-size="11" font-weight="bold" fill="#be185d">• Cüz\'î irade → İnsan sorumluluğu</text>\n  <text x="483" y="208" font-size="11" font-weight="bold" fill="#be185d">• Tevekkül = Tedbir + Dua/Güven</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. ÜNİTE ÖZET TABLOSU: İMAN KAVRAMLARI VE İNSAN TİPLERİ</text>\n  <rect x="25" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Temel İman Terimleri</text>\n  <text x="40" y="95" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Kalp ile Tasdik:</tspan> İmanın asli rüknü (kalben onay)</text>\n  <text x="40" y="117" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Dil ile İkrar:</tspan> İmanı sözle açıklamak</text>\n  <text x="40" y="139" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">İcmâlî İman:</tspan> Toptan ve özet olarak iman</text>\n  <text x="40" y="161" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Tafsîlî İman:</tspan> Ayrıntılarıyla bilerek iman</text>\n  <text x="40" y="183" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">Teklif &amp; Mükellef:</tspan> Akıl ve buluğ ile sorumluluk</text>\n  <text x="40" y="205" font-size="11" fill="#1e3a8a">• <tspan font-weight="bold">İhlas:</tspan> İbadet ve imanda yalnız Allah rızası</text>\n  <text x="40" y="225" font-size="11" font-weight="bold" fill="#1d4ed8">• İman esasları bölünmez bir bütündür.</text>\n\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">İnanç Bakımından İnsanlar</text>\n  <text x="380" y="95" font-size="11" fill="#14532d">• <tspan font-weight="bold">Mümin:</tspan> Kalbiyle tasdik, diliyle ikrar eden</text>\n  <text x="380" y="120" font-size="11" fill="#14532d">• <tspan font-weight="bold">Münafık:</tspan> Kalben inanmadığı hâlde diliyle</text>\n  <text x="390" y="136" font-size="11" fill="#14532d">inandığını söyleyen iki yüzlü kimse (Nifak)</text>\n  <text x="380" y="160" font-size="11" fill="#14532d">• <tspan font-weight="bold">Kâfir:</tspan> İman esaslarını inkâr eden (Küfür)</text>\n  <text x="380" y="184" font-size="11" fill="#14532d">• <tspan font-weight="bold">Müşrik:</tspan> Allah\'a ortak koşan (Şirk)</text>\n  <text x="380" y="208" font-size="11" fill="#14532d">• <tspan font-weight="bold">Fâsık:</tspan> Büyük günah işleyen mümin (Dinden</text>\n  <text x="390" y="224" font-size="11" font-weight="bold" fill="#15803d">çıkmaz, günahkâr mümin kabul edilir).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
